/* ===============================
   34A13B — ADMIN MOCK TEST SERIES
   One App • One System premium polish
   Route: /admin/content/mock-tests/test-series
================================ */

.adminMockSeriesPage {
    max-width: 1220px;
    margin: 0 auto;
    padding-bottom: 72px;
  }
  
  /* HERO */
  
  .adminMockSeriesHero {
    display: grid;
    grid-template-columns: minmax(0, 1.08fr) minmax(420px, 0.92fr);
    align-items: stretch;
    gap: 24px;
    margin-bottom: 26px;
    padding: 36px;
    border-radius: 36px;
    border: 1px solid rgba(15, 23, 42, 0.08);
    background:
      radial-gradient(circle at 8% 16%, rgba(249, 115, 22, 0.15), transparent 34%),
      radial-gradient(circle at 92% 10%, rgba(37, 99, 235, 0.13), transparent 32%),
      linear-gradient(135deg, #ffffff 0%, #fbf7f0 54%, #eef5ff 100%);
    box-shadow:
      0 24px 56px rgba(15, 23, 42, 0.08),
      0 44px 120px rgba(15, 23, 42, 0.07);
    overflow: hidden;
  }
  
  .adminMockSeriesHeroCopy {
    display: flex;
    flex-direction: column;
    justify-content: center;
    min-width: 0;
  }
  
  .adminMockSeriesHero h1 {
    max-width: 780px;
    margin: 16px 0 14px;
    color: #0f172a;
    font-size: clamp(2.65rem, 5.2vw, 5rem);
    line-height: 0.96;
    letter-spacing: -0.075em;
  }
  
  .adminMockSeriesHero p {
    max-width: 760px;
    margin: 0;
    color: #42526b;
    font-size: 1.05rem;
    font-weight: 750;
    line-height: 1.7;
  }
  
  .adminMockSeriesHeroActions,
  .adminMockSeriesBottomActions {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
  }
  
  .adminMockSeriesHeroActions {
    margin-top: 28px;
  }
  
  .adminMockSeriesPrimaryBtn,
  .adminMockSeriesGhostBtn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 50px;
    border-radius: 999px;
    padding: 0 20px;
    font-size: 0.92rem;
    font-weight: 950;
    cursor: pointer;
    white-space: nowrap;
    transition:
      transform 0.2s ease,
      box-shadow 0.2s ease,
      background 0.2s ease,
      border-color 0.2s ease;
  }
  
  .adminMockSeriesPrimaryBtn {
    border: 0;
    color: #ffffff;
    background: #0f172a;
    box-shadow: 0 18px 42px rgba(15, 23, 42, 0.22);
  }
  
  .adminMockSeriesGhostBtn {
    color: #0f172a;
    background: rgba(255, 255, 255, 0.92);
    border: 1px solid rgba(15, 23, 42, 0.1);
    box-shadow: 0 16px 36px rgba(15, 23, 42, 0.08);
  }
  
  .adminMockSeriesPrimaryBtn:hover,
  .adminMockSeriesGhostBtn:hover {
    transform: translateY(-1px);
  }
  
  /* DARK SYSTEM CARD */
  
  .adminMockSeriesSystemCard {
    position: relative;
    min-height: 320px;
    padding: 22px;
    border-radius: 30px;
    color: #ffffff;
    background:
      radial-gradient(circle at 15% 10%, rgba(249, 115, 22, 0.22), transparent 30%),
      radial-gradient(circle at 90% 20%, rgba(59, 130, 246, 0.18), transparent 32%),
      linear-gradient(135deg, #2b1f20 0%, #0f172a 54%, #08111f 100%);
    box-shadow:
      0 24px 52px rgba(15, 23, 42, 0.22),
      0 44px 120px rgba(15, 23, 42, 0.16);
    overflow: hidden;
  }
  
  .adminMockSeriesSystemCard::after {
    content: "";
    position: absolute;
    inset: auto -70px -90px auto;
    width: 210px;
    height: 210px;
    border-radius: 999px;
    background: rgba(249, 115, 22, 0.16);
    filter: blur(24px);
  }
  
  .adminMockSeriesSystemTop {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 24px;
  }
  
  .adminMockSeriesSystemTop span {
    display: inline-flex;
    align-items: center;
    min-height: 34px;
    padding: 0 14px;
    border-radius: 999px;
    color: #fed7aa;
    background: rgba(255, 255, 255, 0.1);
    font-size: 0.78rem;
    font-weight: 950;
    text-transform: uppercase;
    letter-spacing: 0.09em;
  }
  
  .adminMockSeriesSystemTop strong {
    color: #ffffff;
    font-size: 0.95rem;
    font-weight: 950;
  }
  
  .adminMockSeriesSystemGrid {
    position: relative;
    z-index: 1;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px;
  }
  
  .adminMockSeriesSystemGrid div {
    min-height: 102px;
    padding: 18px;
    border-radius: 22px;
    background:
      linear-gradient(135deg, rgba(255, 255, 255, 0.12), rgba(255, 255, 255, 0.06));
    border: 1px solid rgba(255, 255, 255, 0.11);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
  }
  
  .adminMockSeriesSystemGrid strong {
    display: block;
    color: #ffffff;
    font-size: 2rem;
    line-height: 1;
    letter-spacing: -0.05em;
  }
  
  .adminMockSeriesSystemGrid span {
    display: block;
    margin-top: 9px;
    color: rgba(255, 255, 255, 0.78);
    font-size: 0.82rem;
    font-weight: 850;
  }
  
  .adminMockSeriesFlow {
    position: relative;
    z-index: 1;
    display: grid;
    grid-template-columns: auto 1fr auto 1fr auto;
    align-items: center;
    gap: 10px;
    margin-top: 24px;
    padding: 10px 14px;
    border-radius: 999px;
    background: rgba(59, 130, 246, 0.14);
  }
  
  .adminMockSeriesFlow span {
    color: #ffffff;
    font-size: 0.8rem;
    font-weight: 950;
  }
  
  .adminMockSeriesFlow i {
    display: block;
    height: 1px;
    background: rgba(255, 255, 255, 0.24);
  }
  
  /* KPI */
  
  .adminMockSeriesKpiGrid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 16px;
    margin-bottom: 18px;
  }
  
  .adminMockSeriesKpiCard {
    min-height: 146px;
    padding: 22px;
    border-radius: 26px;
    border: 1px solid rgba(15, 23, 42, 0.08);
    background:
      linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.94)),
      #ffffff;
    box-shadow:
      0 18px 36px rgba(15, 23, 42, 0.07),
      0 34px 90px rgba(15, 23, 42, 0.06);
  }
  
  .adminMockSeriesKpiCard span,
  .adminMockSeriesPanelHeader span {
    display: block;
    color: #64748b;
    font-size: 0.76rem;
    font-weight: 950;
    text-transform: uppercase;
    letter-spacing: 0.08em;
  }
  
  .adminMockSeriesKpiCard strong {
    display: block;
    margin-top: 12px;
    color: #0f172a;
    font-size: 2.15rem;
    line-height: 1;
    letter-spacing: -0.05em;
  }
  
  .adminMockSeriesKpiCard p {
    margin: 12px 0 0;
    color: #64748b;
    font-size: 0.88rem;
    font-weight: 800;
    line-height: 1.45;
  }
  
  /* PANEL */
  
  .adminMockSeriesPanel {
    position: relative;
    margin-bottom: 18px;
    padding: 22px;
    border-radius: 30px;
    background:
      radial-gradient(circle at 95% 10%, rgba(249, 115, 22, 0.07), transparent 32%),
      linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.94));
    border: 1px solid rgba(249, 115, 22, 0.18);
    box-shadow:
      0 22px 48px rgba(15, 23, 42, 0.07),
      0 44px 110px rgba(15, 23, 42, 0.055);
    overflow: hidden;
  }
  
  .adminMockSeriesPanel::before {
    content: "";
    position: absolute;
    inset: 12px;
    z-index: 0;
    border-radius: 24px;
    pointer-events: none;
    opacity: 0.78;
    background:
      radial-gradient(circle at 92% 12%, rgba(249, 115, 22, 0.08), transparent 32%),
      radial-gradient(circle at 8% 90%, rgba(37, 99, 235, 0.055), transparent 36%);
  }
  
  .adminMockSeriesPanel > * {
    position: relative;
    z-index: 1;
  }
  
  .adminMockSeriesPanelHeader {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 14px;
    margin-bottom: 18px;
  }
  
  .adminMockSeriesPanelHeader h2 {
    margin: 7px 0 0;
    color: #0f172a;
    font-size: clamp(2.1rem, 4.3vw, 3.6rem);
    line-height: 0.98;
    letter-spacing: -0.065em;
  }
  
  .adminMockSeriesPanelHeader small {
    display: inline-flex;
    align-items: center;
    min-height: 34px;
    padding: 0 13px;
    border-radius: 999px;
    color: #475569;
    background: #f1f5f9;
    font-size: 0.78rem;
    font-weight: 950;
    white-space: nowrap;
  }
  
  /* SERIES CARDS */
  
  .adminMockSeriesGrid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-items: stretch;
    gap: 16px;
  }
  
  .adminMockSeriesCard {
    display: grid;
    grid-template-columns: 56px minmax(0, 1fr) 40px;
    align-items: center;
    gap: 15px;
    min-height: 116px;
    width: 100%;
    text-align: left;
    padding: 18px;
    border-radius: 28px;
    border: 1px solid rgba(15, 23, 42, 0.08);
    background:
      radial-gradient(circle at 94% 12%, rgba(249, 115, 22, 0.07), transparent 32%),
      linear-gradient(135deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.96));
    box-shadow:
      0 14px 28px rgba(15, 23, 42, 0.055),
      0 26px 70px rgba(15, 23, 42, 0.045);
    cursor: pointer;
    overflow: hidden;
    transform: translateY(0);
    transition:
      transform 0.22s ease,
      box-shadow 0.22s ease,
      border-color 0.22s ease;
  }
  
  .adminMockSeriesCard:hover,
  .adminMockSeriesKpiCard:hover {
    transform: translateY(-3px);
    border-color: rgba(249, 115, 22, 0.22);
    box-shadow:
      0 22px 44px rgba(15, 23, 42, 0.09),
      0 40px 100px rgba(15, 23, 42, 0.07);
  }
  
  .adminMockSeriesIcon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 56px;
    height: 56px;
    border-radius: 19px;
    color: #ffffff;
    background: #0f172a;
    box-shadow: 0 16px 32px rgba(15, 23, 42, 0.18);
  }
  
  .adminMockSeriesBody {
    display: block;
    min-width: 0;
  }
  
  .adminMockSeriesBody strong {
    display: block;
    color: #0f172a;
    font-size: 1.08rem;
    font-weight: 950;
    line-height: 1.32;
    letter-spacing: -0.025em;
    overflow-wrap: anywhere;
  }
  
  .adminMockSeriesBody small {
    display: block;
    margin-top: 8px;
    color: #64748b;
    font-size: 0.84rem;
    font-weight: 850;
    line-height: 1.42;
    overflow-wrap: anywhere;
  }
  
  .adminMockSeriesArrow {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: 999px;
    color: #f97316;
    background: #fff7ed;
    font-weight: 950;
    box-shadow: 0 12px 24px rgba(249, 115, 22, 0.12);
  }
  
  /* EMPTY + BOTTOM */
  
  .adminMockSeriesEmpty {
    padding: 24px;
    border-radius: 22px;
    color: #64748b;
    background: rgba(248, 250, 252, 0.94);
    border: 1px dashed rgba(15, 23, 42, 0.16);
    font-size: 0.94rem;
    font-weight: 850;
  }
  
  .adminMockSeriesEmpty strong {
    display: block;
    color: #0f172a;
    font-size: 1rem;
  }
  
  .adminMockSeriesEmpty p {
    margin: 8px 0 0;
    color: #64748b;
    font-weight: 800;
  }
  
  .adminMockSeriesBottomActions {
    justify-content: flex-end;
    margin-top: 20px;
    padding: 18px;
    border-radius: 28px;
    background: #ffffff;
    border: 1px solid rgba(15, 23, 42, 0.08);
    box-shadow:
      0 18px 36px rgba(15, 23, 42, 0.07),
      0 34px 90px rgba(15, 23, 42, 0.06);
  }
  
  /* RESPONSIVE */
  
  @media (max-width: 1080px) {
    .adminMockSeriesHero {
      grid-template-columns: 1fr;
    }
  
    .adminMockSeriesSystemCard {
      min-height: auto;
    }
  
    .adminMockSeriesGrid {
      grid-template-columns: 1fr;
    }
  }
  
  @media (max-width: 860px) {
    .adminMockSeriesKpiGrid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  
    .adminMockSeriesPanelHeader h2 {
      font-size: clamp(1.8rem, 8vw, 2.8rem);
    }
  }
  
  @media (max-width: 640px) {
    .adminMockSeriesPage {
      padding-bottom: 46px;
    }
  
    .adminMockSeriesHero,
    .adminMockSeriesPanel {
      border-radius: 24px;
      padding: 18px;
    }
  
    .adminMockSeriesHero h1 {
      font-size: clamp(2.25rem, 14vw, 3.25rem);
    }
  
    .adminMockSeriesKpiGrid,
    .adminMockSeriesSystemGrid {
      grid-template-columns: 1fr;
    }
  
    .adminMockSeriesHeroActions button,
    .adminMockSeriesBottomActions button {
      width: 100%;
    }
  
    .adminMockSeriesCard {
      grid-template-columns: 48px minmax(0, 1fr) 34px;
    }
  
    .adminMockSeriesIcon {
      width: 48px;
      height: 48px;
    }
  
    .adminMockSeriesArrow {
      width: 34px;
      height: 34px;
    }
  
    .adminMockSeriesBottomActions {
      justify-content: stretch;
    }
  
    .adminMockSeriesCard:hover,
    .adminMockSeriesKpiCard:hover {
      transform: translateY(-1px);
    }
  }

